        results=[],
    )
    print(f"GPU: {properties.name} | SGLang defaults: {report['sglang_configs']}", flush=True)
    print(f"{'Shape':<34} {'T':>7} {'Hg/H':>7} {'SGLang ms':>11} {'FlyDSL ms':>11} {'Speedup':>9}", flush=True)
    with torch.inference_mode():
        for shape in shapes:
